#!/usr/bin/env python3
"""Validate completed checked traces and write the human-readable comparison."""
import csv, hashlib, json, pathlib, statistics
ROOT = pathlib.Path(__file__).resolve().parents[1]
A = ROOT / 'artifacts'

def load(name):
    data = json.loads((A / name).read_text())
    assert data['passed'], name
    return data
normal = load('cpp-modern-final-comparison.json')
mixed = load('cpp-modern-final-mixed.json')
aocl = load('cpp-modern-final-aocl.json')
cap = load('cpp-modern-accepted-100k.json')
build = json.loads((A / 'candidates/cpp-modern/build.json').read_text())
assert normal['server_sha256']['cpp'] == mixed['server_sha256']['cpp'] == cap['server_sha256']['cpp'] == build['binary_sha256']
assert len(normal['runs']) == 36 and len(mixed['runs']) == 6 and (len(aocl['runs']) == 8) and (len(cap['runs']) == 4)
for batch in [normal, mixed, aocl]:
    for row in batch['runs']:
        assert row['passed'] and row['server_exit_code'] == 0
        m = row['final_metrics']
        assert m['war_connections'] == m['war_queued_bytes'] == m['war_variable_bytes'] == 0 and m['war_channels'] == 1
        if row['kind'] in ['cpp', 'glibc', 'aocl']:
            assert m['war_buffered_bytes'] == m['war_retained_output_bytes'] == m['war_slow_consumers_total'] == 0
for row in cap['runs']:
    assert row['passed'] and row['client_exit_code'] == row['server_exit_code'] == 0
    assert hashlib.sha256((ROOT / row['csv']).read_bytes()).hexdigest() == row['csv_sha256']
    data = list(csv.DictReader((ROOT / row['csv']).open()))
    assert len(data) == 100000 and len({r['id'] for r in data}) == 100000 and all((int(r['samples']) == 120 for r in data))
    gates = {g['event']: g for g in row['gates']}
    counts = gates['measured']['details']['counts']
    assert counts['sent_messages'] == counts['deliveries'] == 12000000
    assert gates['done']['counts']['normal_closes'] == 100000 and gates['done']['counts']['departure_checks'] == 750000
    assert row['after']['fd_count'] == row['baseline']['fd_count']
    if row['kind'] == 'cpp':
        assert row['final_metrics']['war_buffered_bytes'] == row['final_metrics']['war_retained_output_bytes'] == 0
summary = {'normal': [], 'capacity': cap['runs'], 'mixed': mixed['runs'], 'aocl': aocl['runs'], 'verified_timed_population_probes': 48000000, 'passed': True}
for workers in [1, 4]:
    for mode in ['traffic', 'fanout', 'churn']:
        for kind in ['rust', 'rust-observer-index', 'cpp']:
            rows = [r for r in normal['runs'] if r['workers'] == workers and r['mode'] == mode and (r['kind'] == kind)]
            summary['normal'].append({'workers': workers, 'mode': mode, 'kind': kind, 'throughput_median': statistics.median((r['result']['deliveries_per_second'] for r in rows)), 'throughput_range': [min((r['result']['deliveries_per_second'] for r in rows)), max((r['result']['deliveries_per_second'] for r in rows))], 'cpu_us_median': statistics.median((r['server_cpu_seconds'] / r['result']['verified_deliveries'] * 1000000.0 for r in rows)), 'p99_upper_ms': [r['result']['latency_p99_upper_ms'] for r in rows]})
(A / 'cpp-modern-analysis.json').write_text(json.dumps(summary, indent=2) + '\n')

def sel(w, m, k):
    return next((r for r in summary['normal'] if (r['workers'], r['mode'], r['kind']) == (w, m, k)))
lines = ['# Modern C++ versus Rust: measured comparison', '', '2026-10-17. The C++20 candidate is a separate static library and CLI. The selected Rust service/default remains unchanged. C++ has a strong populated-memory and multi-worker fanout result; it is not a universal replacement for the best Rust runtime.', '', '## Exact implementations', '', f"- Modern C++ executable SHA-256: `{build['binary_sha256']}`; static library: `{build['library_sha256']}`. {build['compiler']}; `-O3 -march=native -flto=thin`, native epoll, plaintext, compression disabled.", f"- uWebSockets `{build['uws_revision']}`, uSockets `{build['usockets_revision']}`, with the tracked transport patch and source hashes in the archived build record.", '- Selected Rust: runtime commit `c7bb20a103d3266a47ff3f26a6ec1c473d484e5c`, executable `f1bf8bf9fd7c7e8f189806dba4bbdc4441e11ca9f7f680d8d14efe4716cb49be`. Native Mio reactor; Rust 1.91.1 / LLVM 21.1.2; native optimized release build.', '- Newer Rust observer-index candidate: `4c231770f20a9e2d1191fe2db27ba5fbe1d13a82b3257313de4893507e380091`, reconstructed from its recorded base and runtime patch. This candidate remains unselected; its sources/results are preserved independently.', '', '## Saturation workloads', '', 'Fresh sequential processes, rotated runtime order, two 6-second trials per runtime/workload/worker count. Servers have individually verified singleton worker affinity on CPUs 0 through N-1. The same frozen four-thread checked client runs on CPUs 8-15. Private traffic uses 32 pairs; fanout uses one publisher and 63 checked readers; churn uses 16 independent lifecycle workers. Application payloads are 1 KiB; data windows contain 16 messages. Every received payload and its order are checked. No bridge, sanitizer, profiler, build, or concurrent benchmark runs during these timings.', '', 'Values below are medians of two trials. CPU is measured server process CPU, including setup and client cleanup, divided by verified operations; it is not isolated forwarding cost. Churn operations include connect, upgrade, join, checked self-delivery, Close acknowledgement and EOF.', '', '| Workers | Workload | Selected Rust ops/s | Observer Rust ops/s | C++ ops/s | Selected Rust CPU µs/op | Observer Rust CPU µs/op | C++ CPU µs/op |', '|---:|---|---:|---:|---:|---:|---:|---:|']
for w in [1, 4]:
    for mode in ['traffic', 'fanout', 'churn']:
        r, i, c = [sel(w, mode, k) for k in ['rust', 'rust-observer-index', 'cpp']]
        lines.append(f"| {w} | {mode} | {r['throughput_median']:,.0f} | {i['throughput_median']:,.0f} | {c['throughput_median']:,.0f} | {r['cpu_us_median']:.3f} | {i['cpu_us_median']:.3f} | {c['cpu_us_median']:.3f} |")
lines += ['', 'The four-worker C++ fanout gain comes with greater CPU per delivered message. Private traffic is slower and less CPU-efficient than selected Rust. Churn is close at four workers; a small throughput difference is not a strong win given two trials. Fresh SO_REUSEPORT placements vary between trials; the full ranges and p99 histogram bounds are retained in the raw traces. The comparison does not establish a language-wide ranking.', '', '![Throughput and CPU](../docs/benchmarks/2026-10-17-modern-cpp/cpp-modern-throughput.png)', '', '## 100,000-user responsiveness and memory', '', 'Each of four fresh processes admits 100,000 distinct live users in 16-member rooms, routes a proof through every connection, runs 400,000 verified private probes/s for 30 seconds, proves every connection again, and checks complete retirement. Each user contributes 120 exact latency samples. Across the four runs, 48,000,000 timed probes are verified. Server CPU is captured between the ready/measured gates, excluding setup and CSV sorting/output. Eight server workers are pinned to CPUs 0-7; eight client workers run on 8-15. Both servers request 16 KiB send and 64 KiB receive buffers; heartbeat and rate limits are disabled in both.', '', 'RSS/PSS/private memory are sampled with the full population at the ready gate; these are process memory, not kernel TCP memory or client memory. After-retirement RSS is also shown because C++ retains more resident allocator/container capacity after clients leave. Logical gauges and file descriptors return to their starting state. Latency includes client scheduling and room batching; it is not a measurement of the isolated relay hop.', '', '| Runtime/trial | Populated RSS MiB | Populated private MiB | After RSS MiB | Server CPU-s | Median user p99 ms | p99 of users’ p99 ms | Worst user p99 ms | Worst packet ms |', '|---|---:|---:|---:|---:|---:|---:|---:|---:|']
for r in cap['runs']:
    lines.append(f"| {r['kind']} {r['repeat']} | {r['population_rss_kib'] / 1024:.2f} | {r['measured_before']['private_kib'] / 1024:.2f} | {r['after']['rss_kib'] / 1024:.2f} | {r['server_cpu_seconds']:.2f} | {r['p99_ms']['median']:.3f} | {r['p99_ms']['p99']:.3f} | {r['p99_ms']['max']:.3f} | {r['max_ms']['max']:.3f} |")
lines += ['', 'The per-user CDFs keep all 100,000 users visible rather than combining their traffic into one population-wide percentile. Intended-send latency additionally includes time spent waiting for the load client to issue its probe. Thirty seconds and two repeats do not establish long-duration or hostile-load reliability.', '', '![Per-user latency](../docs/benchmarks/2026-10-17-modern-cpp/cpp-modern-user-fairness.png)', '', '## Competing traffic and observers', '', 'Same frozen inspection client and native CBOR controls in all implementations: 512 authenticated global channel observers, one private pair, 64 idle rooms, eight churn workers, and two CBOR inspectors querying every 10 ms. Four pinned server workers, eight client workers, 1 KiB payloads, 16-frame fanout windows, two 6-second fresh trials. Setup/cleanup gates use the protocol; there is no HTTP inspection in this case. The p99 values are logarithmic histogram upper bounds and include client windows. CPU includes every competing operation plus setup/teardown.', '', '| Runtime/trial | Observer deliveries/s | Private p99 upper ms | Churn p99 upper ms | Inspection p99 upper ms |', '|---|---:|---:|---:|---:|']
for r in mixed['runs']:
    x = r['result']
    lines.append(f"| {r['kind']} {r['repeat']} | {x['fanout']['per_second']:,.0f} | {x['healthy']['p99_upper_ms']:.3f} | {x['churn']['p99_upper_ms']:.3f} | {x['inspection']['p99_upper_ms']:.3f} |")
lines += ['', 'C++ carries more observer traffic, but the newer Rust observer candidate has lower private p99 bounds here. A single private pair is sensitive to connection/worker placement; throughput variation in that pair is not used as a general capacity claim. Aggregate fanout throughput alone does not satisfy the platform’s latency priority.', '', '![Competing latency](../docs/benchmarks/2026-10-17-modern-cpp/cpp-modern-mixed-latency.png)', '', '## AOCL and retained experiments', '', 'The optional server-only AOCL LibMem 5.3.2 dispatcher test verifies the loaded library mapping and SHA; the client is never preloaded. The final C++ binary is identical in both arms. Two rotated five-second trials per mode use the same 64-client, 1 KiB workloads.', '', '| Mode | glibc median ops/s | AOCL median ops/s | AOCL / glibc |', '|---|---:|---:|---:|']
for mode in ['traffic', 'fanout']:
    g = statistics.median((r['result']['deliveries_per_second'] for r in aocl['runs'] if r['mode'] == mode and r['kind'] == 'glibc'))
    a = statistics.median((r['result']['deliveries_per_second'] for r in aocl['runs'] if r['mode'] == mode and r['kind'] == 'aocl'))
    lines.append(f'| {mode} | {g:,.0f} | {a:,.0f} | {a / g:.3f}× |')
lines += ['', 'AOCL is not enabled by default: the private result is inconsistent across pairs and fanout regresses in both pairs. The batched mailbox drain is retained after both measured pairs improved. A per-worker-counter experiment and early private-guard-release experiment did not earn adoption in their short end-to-end trials. Those controls were earlier C++ builds, even though their raw harness inherited the key `rust`; the archived binary hashes and experiment label map identify them as C++ controls. No benefit is claimed from the rejected variants.', '', '## Verification and remaining differences', '', '- Full unchanged shared corpus: 776 cases / 2,311 exchanges. Exact opaque CBOR values, malformed values/frames, fragmented and pipelined input, variable isolation, disconnect events and final resource cleanup.', '- Full corpus passes separately under AddressSanitizer + UndefinedBehaviorSanitizer and ThreadSanitizer. CMake boundary tests and three repeated embedded stop-token lifecycles pass. These are finite campaigns, not an exhaustive race/fuzzing proof.', '- Runtime checks cover observer scope/deduplication and opt-out barriers, variables, ID takeover, unauthorized controls, active shutdown, incomplete-HTTP shutdown and failed-bind worker unwinding.', '- A real unread destination receives Close 1013 while healthy payloads/order continue; after retirement, connections, users, queued bytes, output bytes and variable bytes are zero. Transport-close ownership prevents early admission/budget release.', '- The transport patch fixes the observed stock dependency differences: all 22 whole-frame transport probes now match the shared expectations, followed by the full three-mode corpus.', '- Application CBOR validation uses a fixed stack and no object graph; local forwarding borrows receive payload bytes where prefix space permits. Cross-thread output requires one shared ownership copy, and uWebSockets still copies small frames into its transport storage. It is not end-to-end zero-copy.', '', 'C++ does not yet offer the complete Rust origin/per-IP admission policy, aggregate decoder-memory budget/reclamation, heartbeat, separate application/join/write deadlines, rate buckets, graceful drain administration, authenticated channel-inspection JSON or full metrics schema. Its current API binds plaintext loopback. Automatic transport/control allocation is reconciled rather than a strict allocator-wide admission cap. Consequently these healthy, same-host workload comparisons do not establish production feature parity or a guarantee that arbitrary 100,000-user workloads cannot fail.', '', 'Keep the selected Rust service for the present low-latency operating recommendation. Preserve C++ as the concrete lower-populated-memory and parallel-fanout alternative, and use the measured cross-thread output, metadata/fanout scheduling and retained-memory costs to guide subsequent work.', '', 'Raw traces, compressed per-user CSVs, plots, source snapshots, build records, sanitizer logs, experiment controls and a SHA-256 manifest are in [the benchmark archive](../docs/benchmarks/2026-10-17-modern-cpp/README.md). No manual relay service was replaced, and no production deployment or push was performed.']
(ROOT / 'cpp/BENCHMARKS.md').write_text('\n'.join(lines) + '\n')
print('Validated completed traces and wrote cpp/BENCHMARKS.md')
